*{box-sizing:border-box} :root{--bg:#07100f;--panel:#0b1715;--line:#1a2a27;--muted:#71817c;--text:#e5eee9;--green:#b7f36a;--mint:#64d9ae;--orange:#f2a45e;--red:#ff6673;font-family:'Space Grotesk',sans-serif;color:var(--text);font-synthesis:none}html,body{margin:0;min-height:100%;background:var(--bg)}body{background-image:linear-gradient(rgba(67,116,94,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(67,116,94,.025) 1px,transparent 1px);background-size:34px 34px}.shell{max-width:1600px;margin:auto;padding:0 40px}.topbar{height:74px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;color:var(--text);text-decoration:none;font-size:15px;font-weight:700;letter-spacing:.18em}.brand-mark{display:grid;place-items:center;width:27px;height:27px;border:1px solid var(--green);color:var(--green);font:500 17px 'DM Mono';transform:rotate(45deg)}.brand-mark::first-letter{transform:rotate(-45deg)}.brand-dot{color:var(--green)}.top-meta,.icon-btn,.eyebrow,.rail-label,.rail-footer,.panel-title,.pill,.canvas-topline,.game-bottom,.page-footer,.start-kicker,.start-hint,.primary-btn,.objective-list,.intel-note b,.weapon-key,.meter-label,.score-sub,.signal-legend{font-family:'DM Mono',monospace}.top-meta{color:#8e9b96;font-size:10px;letter-spacing:.11em;display:flex;align-items:center;gap:9px}.live-dot,.tiny-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 11px #b7f36699}.divider{color:#34413d}.icon-btn{background:transparent;color:#899791;border:1px solid var(--line);padding:8px 11px;font-size:10px;letter-spacing:.06em;cursor:pointer}.icon-btn span{margin-left:7px}.game-layout{display:grid;grid-template-columns:205px minmax(500px,1fr) 220px;gap:26px;padding:27px 0 20px;align-items:start}.left-rail,.right-rail{min-width:0}.rail-label{font-size:10px;color:#85928c;letter-spacing:.12em;padding:8px 0 12px;border-bottom:1px solid var(--line);