function renderObjectives(){if(!game)return;let rows=[{text:missions[mapIndex].console,done:game.console},{text:missions[mapIndex].target,done:game.hasIntel},{text:'Alcanzar extracción',done:game.complete}];$('objectiveList').innerHTML=rows.map(o=>`<div class="objective-item ${o.done?'done':''}"><span class="objective-check">${o.done?'✓':''}</span>${o.text}</div>`).join('');}
function resize(){const box=canvas.getBoundingClientRect();dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(box.width*dpr));canvas.height=Math.max(1,Math.floor(box.height*dpr));view.scale=Math.min(canvas.width/W,canvas.height/H);view.x=(canvas.width-W*view.scale)/2;view.y=(canvas.height-H*view.scale)/2;drawAll();}
function roundRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);}
function drawAll(){if(!game||!canvas.width)return;ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle=missions[mapIndex].tint;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.setTransform(view.scale,0,0,view.scale,view.x,view.y);drawWorld();drawRadar();}
function drawWorld(){const m=missions[mapIndex],t=game.tick;ctx.fillStyle=mapIndex===1?'#11201f':mapIndex===2?'#18231b':'#111d19';ctx.fillRect(0,0,W,H);
  // Floor panels and ambient pools of light.
  for(let y=24;y<H-22;y+=48)for(let x=24;x<W-22;x+=48){ctx.fillStyle=((x/48+y/48)%2<1)?'#ffffff03':'#00000004';ctx.fillRect(x,y,46,46);ctx.strokeStyle='#c9e6d208';ctx.strokeRect(x+.5,y+.5,46,46);}
  const glow=ctx.createRadialGradient(170,340,20,170,340,260);glow.addColorStop(0,'#a4d47b0a');glow.addColorStop(1,'#a4d47b00');ctx.fillStyle=glow;ctx.fillRect(20,40,520,560);
  // lanes / map-specific markings
  ctx.strokeStyle=mapIndex===1?'#6d9d8b15':'#9ab59a12';ctx.lineWidth=1;for(let x=42;x<W;x+=96){ctx.beginPath();ctx.moveTo(x,24);ctx.lineTo(x,H-24);ctx.stroke();}
  game.bushes.forEach(b=>{ctx.fillStyle='#153025';roundRect(ctx,b.x,b.y,b.w,b.h,11);ctx.fill();ctx.strokeStyle='#40734a66';ctx.setLineDash([4,5]);ctx.stroke();ctx.setLineDash([]);for(let i=0;i<5;i++){ctx.fillStyle=`#6db274${i%2?'15':'20'}`;ctx.beginPath();ctx.arc(b.x+12+i*b.w/5,b.y+b.h/2+Math.sin(i*3)*6,12,0,TAU);ctx.fill();}});
  game.walls.forEach(w=>{ctx.fillStyle='#26342f';roundRect(ctx,w.x,w.y,w.w,w.h,3);ctx.fill();ctx.strokeStyle='#52635a';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#d5dfd40b';ctx.fillRect(w.x+3,w.y+3,Math.max(0,w.w-6),2);});
  game.props.forEach(p=>drawProp(p));
  game.objects.forEach(o=>drawObject(o,t));
  game.cams.forEach(c=>drawCamera(c,t));
  game.guards.forEach(g=>drawGuard(g,t));
  game.smokes.forEach(s=>{ctx.fillStyle=`rgba(151,177,163,${.19*s.life})`;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,TAU);ctx.fill();});
  game.decoys.forEach(d=>{ctx.strokeStyle=`rgba(183,243,106,${Math.max(.15,d.life)})`;ctx.lineWidth=2;ctx.beginPath();ctx.arc(d.x,d.y,10+Math.sin(t*7)*4,0,TAU);ctx.stroke();});
  game.noisePings.forEach(p=>{ctx.strokeStyle=`rgba(183,243,106,${p.life*.55})`;ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(p.x,p.y,(1-p.life)*45,0,TAU);ctx.stroke();});
  shotFx.forEach(s=>{ctx.strokeStyle=`rgba(220,248,172,${s.life})`;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x+Math.cos(s.a)*s.len,s.y+Math.sin(s.a)*s.len);ctx.stroke();});
  particles.forEach(p=>{ctx.fillStyle=`rgba(${p.color},${p.life})`;ctx.fillRect(p.x,p.y,3,3);});
  drawPlayer(game.player,t);
  // map frame / edge labels
  ctx.fillStyle='#9cb1a222';ctx.font='9px DM Mono, monospace';ctx.fillText('N ↑',946,45);ctx.fillText('UMBRA // '+String(mapIndex+1).padStart(2,'0'),35,638);
}
function drawProp(p){const colors={desk:['#293a33','#53665a'],server:['#1b2c2d','#537276'],crate:['#473a2d','#806448'],planter:['#263a2a','#58784d']};const [base,edge]=colors[p.kind]||colors.desk;ctx.fillStyle='#00000055';roundRect(ctx,p.x+3,p.y+5,p.w,p.h,4);ctx.fill();ctx.fillStyle=base;roundRect(ctx,p.x,p.y,p.w,p.h,4);ctx.fill();ctx.strokeStyle=edge;ctx.lineWidth=1;ctx.stroke();if(p.kind==='server'){for(let i=0;i<3;i++){ctx.fillStyle=i===1?'#85d5a077':'#a2b3a744';ctx.fillRect(p.x+8,p.y+7+i*8,p.w-16,3);ctx.fillStyle='#8fffc1';ctx.fillRect(p.x+p.w-9,p.y+8+i*8,2,2);}}else if(p.kind==='desk'){ctx.fillStyle='#c8d8c822';ctx.fillRect(p.x+7,p.y+7,p.w*.55,3);ctx.fillStyle='#9be17c55';ctx.beginPath();ctx.arc(p.x+p.w-12,p.y+12,3,0,TAU);ctx.fill();}else if(p.kind==='planter'){ctx.fillStyle='#527b4a';for(let i=0;i<4;i++){ctx.beginPath();ctx.arc(p.x+15+i*(p.w-25)/3,p.y+p.h/2,9,0,TAU);ctx.fill();}}else{ctx.strokeStyle='#90775a55';ctx.beginPath();ctx.moveTo(p.x+5,p.y+5);ctx.lineTo(p.x+p.w-5,p.y+p.h-5);ctx.moveTo(p.x+p.w-5,p.y+5);ctx.lineTo(p.x+5,p.y+p.h-5);ctx.stroke();}}
function drawObject(o,t){const color=o.type==='exit'?'#75d8ae':o.type==='intel'?'#d8c776':'#9dda72';if(o.type==='exit'&&game.complete){ctx.fillStyle='#62d9ae12';ctx.beginPath();ctx.arc(o.x,o.y,30+Math.sin(t*3)*4,0,TAU);ctx.fill();}ctx.save();ctx.translate(o.x,o.y);ctx.strokeStyle=color;ctx.fillStyle=color+'22';ctx.lineWidth=1.5;if(o.type==='console'){ctx.fillRect(-14,-10,28,20);ctx.strokeRect(-14,-10,28,20);ctx.fillStyle=color;ctx.fillRect(-9,-5,18,2);ctx.fillRect(-9,0,12,2);ctx.beginPath();ctx.arc(0,-18,5+Math.sin(t*4)*1,0,TAU);ctx.stroke();}else if(o.type==='intel'){ctx.rotate(Math.PI/4);ctx.fillRect(-9,-9,18,18);ctx.strokeRect(-9,-9,18,18);ctx.rotate(-Math.PI/4);ctx.fillStyle=color;ctx.font='12px monospace';ctx.fillText('◆',-5,4);}else{ctx.beginPath();ctx.arc(0,0,18+Math.sin(t*3)*2,0,TAU);ctx.fill();ctx.stroke();ctx.beginPath();ctx.arc(0,0,9,0,TAU);ctx.stroke();ctx.fillStyle=color;ctx.font='10px monospace';ctx.fillText('E',-3,3);}ctx.restore();}
function drawCamera(c,t){if(c.disabled>0)return;ctx.save();ctx.globalAlpha=.16;ctx.fillStyle='#e2af55';ctx.beginPath();ctx.moveTo(c.x,c.y);ctx.arc(c.x,c.y,165,c.angle-.42,c.angle+.42);ctx.closePath();ctx.fill();ctx.restore();ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.angle);ctx.fillStyle='#67746a';roundRect(ctx,-9,-7,18,14,3);ctx.fill();ctx.fillStyle='#e2af55';ctx.beginPath();ctx.arc(3,0,3,0,TAU);ctx.fill();ctx.restore();}
function drawGuard(g,t){ctx.save();ctx.translate(g.x,g.y);ctx.rotate(g.angle);if(!g.civilian&&g.state!=='stun'){ctx.globalAlpha=.12;ctx.fillStyle=g.state==='chase'?'#ff5363':'#f1bd62';ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,125,-.48,.48);ctx.closePath();ctx.fill();ctx.globalAlpha=1;}ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(1,5,11,7,0,0,TAU);ctx.fill();ctx.fillStyle=g.civilian?'#a4b9b0':g.state==='stun'?'#829087':g.state==='chase'?'#d94f5a':'#b87655';ctx.beginPath();ctx.arc(0,0,9,0,TAU);ctx.fill();ctx.fillStyle=g.civilian?'#d5e0d9':'#e8c9a1';ctx.beginPath();ctx.arc(3,-2,4,0,TAU);ctx.fill();ctx.fillStyle=g.civilian?'#92ada2':'#4a2d25';ctx.fillRect(-8,6,16,3);if(g.state==='chase'){ctx.fillStyle='#ff6673';ctx.fillRect(-2,-18,4,4);}if(g.state==='stun'){ctx.fillStyle='#a7d6ff';ctx.font='11px sans-serif';ctx.fillText('✦',-4,-13);}ctx.restore();}
function drawPlayer(p,t){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.fillStyle='#0009';ctx.beginPath();ctx.ellipse(0,6,13,8,0,0,TAU);ctx.fill();ctx.fillStyle=p.hidden?'#426a4c':'#b7f36a';ctx.beginPath();ctx.arc(0,0,10,0,TAU);ctx.fill();ctx.fillStyle='#d9f6b6';ctx.beginPath();ctx.arc(3,-2,4,0,TAU);ctx.fill();ctx.fillStyle='#2c4632';ctx.fillRect(2,-4,12,4);ctx.fillStyle='#e9efcf';ctx.fillRect(10,-2,7,2);ctx.restore();if(p.hidden){ctx.strokeStyle='#b7f36a66';ctx.beginPath();ctx.arc(p.x,p.y,15+Math.sin(t*4)*2,0,TAU);ctx.stroke();}}
function drawRadar(){if(!rctx||!game)return;const w=radar.width,h=radar.height;rctx.clearRect(0,0,w,h);rctx.fillStyle='#091411';rctx.fillRect(0,0,w,h);rctx.save();rctx.scale(w/W,h/H);rctx.fillStyle='#34463b';game.walls.forEach(a=>rctx.fillRect(a.x,a.y,a.w,a.h));game.props.forEach(a=>{rctx.fillStyle='#24342b';rctx.fillRect(a.x,a.y,a.w,a.h);});game.objects.forEach(o=>{rctx.fillStyle=o.type==='exit'?'#64d9ae':o.type==='intel'?'#e4d27d':'#9dda72';rctx.fillRect(o.x-4,o.y-4,8,8);});game.cams.forEach(c=>{if(c.disabled<=0){rctx.fillStyle='#e2af55';rctx.fillRect(c.x-3,c.y-3,6,6);}});game.guards.forEach(g=>{rctx.fillStyle=g.civilian?'#7b9b90':g.state==='stun'?'#7398bd':'#ff6673';rctx.beginPath();rctx.arc(g.x,g.y,4,0,TAU);rctx.fill();});rctx.fillStyle=COLORS.green;rctx.beginPath();rctx.arc(game.player.x,game.player.y,5,0,TAU);rctx.fill();rctx.strokeStyle=COLORS.green;rctx.beginPath();rctx.moveTo(game.player.x,game.player.y);rctx.lineTo(game.player.x+Math.cos(game.player.angle)*15,game.player.y+Math.sin(game.player.angle)*15);rctx.stroke();rctx.restore();}

