function drawRadar(){if(!rctx||!game)return;const w=radar.width,h=radar.height;rctx.clearRect(0,0,w,h);rctx.fillStyle='#091411';rctx.fillRect(0,0,w,h);rctx.save();rctx.scale(w/W,h/H);rctx.fillStyle='#34463b';game.walls.forEach(a=>rctx.fillRect(a.x,a.y,a.w,a.h));game.props.forEach(a=>{rctx.fillStyle='#24342b';rctx.fillRect(a.x,a.y,a.w,a.h);});game.objects.forEach(o=>{rctx.fillStyle=o.type==='exit'?'#64d9ae':o.type==='intel'?'#e4d27d':'#9dda72';rctx.fillRect(o.x-4,o.y-4,8,8);});game.cams.forEach(c=>{if(c.disabled<=0){rctx.fillStyle='#e2af55';rctx.fillRect(c.x-3,c.y-3,6,6);}});game.guards.forEach(g=>{rctx.fillStyle=g.civilian?'#7b9b90':g.state==='stun'?'#7398bd':'#ff6673';rctx.beginPath();rctx.arc(g.x,g.y,4,0,TAU);rctx.fill();});rctx.fillStyle=COLORS.green;rctx.beginPath();rctx.arc(game.player.x,game.player.y,5,0,TAU);rctx.fill();rctx.strokeStyle=COLORS.green;rctx.beginPath();rctx.moveTo(game.player.x,game.player.y);rctx.lineTo(game.player.x+Math.cos(game.player.angle)*15,game.player.y+Math.sin(game.player.angle)*15);rctx.stroke();rctx.restore();}
function overlapCircleRect(x,y,r,a){const px=Math.max(a.x,Math.min(x,a.x+a.w)),py=Math.max(a.y,Math.min(y,a.y+a.h));return (x-px)**2+(y-py)**2<r*r;}
function blocked(x,y,r=10){return game.walls.concat(game.props).some(a=>overlapCircleRect(x,y,r,a));}
function clearLine(x1,y1,x2,y2){const n=Math.ceil(Math.hypot(x2-x1,y2-y1)/10);for(let i=1;i<n;i++){const x=x1+(x2-x1)*i/n,y=y1+(y2-y1)*i/n;if(game.walls.concat(game.props).some(a=>x>a.x&&x<a.x+a.w&&y>a.y&&y<a.y+a.h))return false;}return true;}
function angleDiff(a,b){return Math.atan2(Math.sin(a-b),Math.cos(a-b));}
function inBush(x,y){return game.bushes.some(b=>x>b.x&&x<b.x+b.w&&y>b.y&&y<b.y+b.h);}
function eventWorld(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*dpr/view.scale-view.x/view.scale,y:(e.clientY-r.top)*dpr/view.scale-view.y/view.scale};}
function setAim(e){pointer=eventWorld(e);game.player.angle=Math.atan2(pointer.y-game.player.y,pointer.x-game.player.x);}
function startGame(){if(!game.started){game.started=true;$('startScreen').classList.add('hidden');notify('OPERACIÓN INICIADA · RECUPERA EL OBJETIVO');}else if(game.complete||game.failed)freshGame(mapIndex);}
function notify(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}
function ping(x,y,life=1){game.noisePings.push({x,y,life});}
function playTone(freq=500,dur=.07){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur);}catch(_){}}
function interact(){if(!game.started||game.complete||game.failed)return;const p=game.player;let o=game.objects.find(a=>Math.hypot(a.x-p.x,a.y-p.y)<42);if(!o){notify('NO HAY NADA QUE INTERACTUAR');return;}if(o.type==='console'){if(game.console){notify('TERMINAL YA DESACTIVADA');return;}game.console=true;game.alert=Math.max(0,game.alert-20);game.cams.forEach(c=>c.disabled=99);game.score+=450;notify('RED DE SEGURIDAD DESACTIVADA · +450');playTone(730);renderObjectives();updateHUD();}else if(o.type==='intel'){if(!game.console){notify('DESACTIVA LA RED DE SEGURIDAD PRIMERO');return;}if(game.hasIntel){notify('ARCHIVO ASEGURADO');return;}game.hasIntel=true;game.score+=1000;notify('OBJETIVO ASEGURADO · EXTRACCIÓN ACTIVADA');playTone(900);renderObjectives();updateHUD();}else if(o.type==='exit'){if(!game.hasIntel){notify('EXTRACCIÓN BLOQUEADA · FALTA EL OBJETIVO');return;}game.complete=true;game.score+=Math.max(100,Math.floor(600-elapsed*3))+Math.max(0,400-game.alert*4);game.alert=0;notify('MISIÓN COMPLETADA · EXTRACCIÓN LIMPIA');playTone(1000,.2);renderObjectives();updateHUD();$('startScreen').innerHTML='<div class="start-inner"><div class="start-kicker"><span class="live-dot"></span> OPERACIÓN COMPLETADA</div><div class="start-logo">FANTASMA<br><span>CONFIRMADO.</span></div><p>El objetivo está a salvo. La ciudad nunca sabrá que estuviste aquí.</p><button class="primary-btn" id="againBtn">VOLVER A DESPLEGAR <span>↻</span></button></div>';$('startScreen').classList.remove('hidden');$('againBtn').onclick=()=>freshGame(mapIndex);}}
function useGadget(){if(!game.started||game.complete||game.failed)return;const idx=selectedGadget, p=game.player;if(game.gadgets[idx]<=0){notify('SIN CARGAS DISPONIBLES');return;}if(idx===0){game.smokes.push({x:p.x,y:p.y,life:1,r:105});game.gadgets[idx]--;notify('BOMBA DE HUMO · CORTA LÍNEA DE VISIÓN');ping(p.x,p.y,.3);}else if(idx===1){const x=p.x+Math.cos(p.angle)*85,y=p.y+Math.sin(p.angle)*85;if(blocked(x,y,3)){notify('NO HAY ESPACIO PARA EL SEÑUELO');return;}game.decoys.push({x,y,life:5});game.gadgets[idx]--;ping(x,y);notify('SEÑUELO ACTIVO · LOS GUARDIAS INVESTIGARÁN');}else{const affected=game.cams.filter(c=>Math.hypot(c.x-p.x,c.y-p.y)<210&&c.disabled<=0);if(!affected.length){notify('EMP: NINGÚN SENSOR EN ALCANCE');return;}affected.forEach(c=>c.disabled=8);game.guards.filter(g=>!g.civilian&&Math.hypot(g.x-p.x,g.y-p.y)<115).forEach(g=>g.stun=2.2);game.gadgets[idx]--;notify('PULSO EMP · SENSORES CEGADOS');}playTone(310);renderLoadout();}
let selectedGadget=0;
function fire(){if(!game.started||game.complete||game.failed)return;const p=game.player,w=weapons[game.weapon];if(w.ammo<=0){notify('SIN MUNICIÓN · PULSA R PARA RECARGAR');return;}w.ammo--;game.shots.push({x:p.x,y:p.y,a:p.angle,len:35,life:.28});game.combatTimer=1;ping(p.x+Math.cos(p.angle)*25,p.y+Math.sin(p.angle)*25,Math.max(.25,w.noise/40));let hit=null,dist=10000;for(const g of game.guards){if(g.civilian||g.state==='stun')continue;const dx=g.x-p.x,dy=g.y-p.y,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx);if(d<w.range&&d<dist&&Math.abs(angleDiff(a,p.angle))<.12&&clearLine(p.x,p.y,g.x,g.y)){hit=g;dist=d;}}if(hit){hit.stun=game.weapon===2?5:3.2;hit.state='stun';hit.alerted=false;game.score+=game.weapon===1?260:180;notify(game.weapon===1?'HOSTIL NEUTRALIZADO · NO LETAL':'HOSTIL DESACTIVADO');for(let i=0;i<8;i++)particles.push({x:hit.x,y:hit.y,life:1,color:'151,209,255',vx:(Math.random()-.5)*60,vy:(Math.random()-.5)*60});}else if(w.noise>20){game.alert=Math.min(100,game.alert+6);notify('DISPARO DETECTADO');}playTone(game.weapon===1?780:360,.045);updateHUD();renderLoadout();}
function reload(){const w=weapons[game.weapon];if(w.ammo===w.max){notify('CARGADOR COMPLETO');return;}w.ammo=w.max;notify('RECARGADO');playTone(540);renderLoadout();}
function takedown(){if(!game.started||game.complete)return;const p=game.player, g=game.guards.filter(a=>!a.civilian&&a.state!=='stun'&&Math.hypot(a.x-p.x,a.y-p.y)<34).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(!g){notify('ACÉRCATE A UN HOSTIL PARA DERRIBARLO');return;}if(Math.abs(angleDiff(Math.atan2(p.y-g.y,p.x-g.x),g.angle))<.85&&g.state!=='chase'){notify('MAL ÁNGULO · ACÉRCATE POR DETRÁS');return;}g.state='stun';g.stun=5;game.score+=320;notify('DERRIBO SILENCIOSO · +320');playTone(220);updateHUD();}
function whistle(){if(!game.started)return;ping(game.player.x,game.player.y,.7);notify('SILBIDO · RUIDO EN TU POSICIÓN');game.alert=Math.min(100,game.alert+2);}

