function whistle(){if(!game.started)return;ping(game.player.x,game.player.y,.7);notify('SILBIDO · RUIDO EN TU POSICIÓN');game.alert=Math.min(100,game.alert+2);}
function update(dt){if(!game)return;game.tick+=dt;game.cooldown=Math.max(0,game.cooldown-dt);if(game.started&&!game.complete&&!game.failed){elapsed+=dt;const p=game.player;const stealth=keys.ShiftLeft||keys.ShiftRight;let dx=(keys.KeyD?1:0)-(keys.KeyA?1:0),dy=(keys.KeyS?1:0)-(keys.KeyW?1:0);if(touchVector.x||touchVector.y){dx=touchVector.x;dy=touchVector.y;}let mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag;}const sprint=(keys.ControlLeft||keys.ControlRight)&&p.stamina>2&&!stealth;const speed=stealth?82:sprint?225:150;if(sprint&&mag)p.stamina=Math.max(0,p.stamina-34*dt);else p.stamina=Math.min(100,p.stamina+22*dt);if(mag){let nx=p.x+dx*speed*dt,ny=p.y+dy*speed*dt;if(!blocked(nx,p.y,p.r))p.x=nx;if(!blocked(p.x,ny,p.r))p.y=ny;if(!pointer.down&&!(touchVector.x||touchVector.y))p.angle=Math.atan2(dy,dx);p.noise=stealth?0.12:sprint?.8:.38; if(p.noise>.6&&Math.random()<dt*2)ping(p.x,p.y,.3);}p.x=Math.max(34,Math.min(W-34,p.x));p.y=Math.max(34,Math.min(H-34,p.y));p.hidden=inBush(p.x,p.y)&&stealth;
    game.smokes.forEach(s=>s.life-=dt*.16);game.smokes=game.smokes.filter(s=>s.life>0);game.decoys.forEach(d=>d.life-=dt);game.decoys=game.decoys.filter(d=>d.life>0);game.noisePings.forEach(a=>a.life-=dt*.6);game.noisePings=game.noisePings.filter(a=>a.life>0);game.cams.forEach(c=>{if(c.disabled>0)c.disabled-=dt;else c.angle=c.base+Math.sin(game.tick*.6+c.x)*.22;});
    let spotted=false;
    for(const c of game.cams){if(c.disabled>0)continue;const d=Math.hypot(p.x-c.x,p.y-c.y),a=Math.atan2(p.y-c.y,p.x-c.x);if(d<155&&Math.abs(angleDiff(a,c.angle))<.43&&clearLine(c.x,c.y,p.x,p.y)&&!p.hidden&&!game.smokes.some(s=>Math.hypot(s.x-p.x,s.y-p.y)<s.r)){spotted=true;game.alert=Math.min(100,game.alert+dt*13);}}
    for(const g of game.guards){if(g.stun>0){g.stun-=dt;if(g.stun<=0){g.state='patrol';g.index=(g.index+1)%g.points.length;}continue;}if(g.civilian){const d=Math.hypot(g.x-p.x,g.y-p.y);if(d<85&&!p.hidden&&p.noise>.65){game.alert=Math.min(100,game.alert+dt*3);}movePatrol(g,dt);continue;}
      const dist=Math.hypot(p.x-g.x,p.y-g.y),bearing=Math.atan2(p.y-g.y,p.x-g.x);const fov=Math.abs(angleDiff(bearing,g.angle))<.68;const sees=dist<205&&fov&&clearLine(g.x,g.y,p.x,p.y)&&!p.hidden&&!game.smokes.some(s=>Math.hypot(s.x-p.x,s.y-p.y)<s.r);
      if(sees){spotted=true;g.state='chase';g.alerted=true;g.search=3.5;game.alert=Math.min(100,game.alert+dt*(dist<90?24:11));}
      if(g.state==='chase'){if(dist<190&&clearLine(g.x,g.y,p.x,p.y)){g.angle=bearing;moveToward(g,p.x,p.y,dt,g.speed*1.22);g.search=3.5;}else{g.search-=dt;if(g.search<=0){g.state='search';g.look=2.5;}}if(dist<21){g.look-=dt;if(g.look<=0){p.hp=Math.max(0,p.hp-18);g.look=1.5;game.score=Math.max(0,game.score-30);$('canvasWrap').classList.add('shake');setTimeout(()=>$('canvasWrap').classList.remove('shake'),300);notify('GOLPE RECIBIDO · ROMPE CONTACTO');if(p.hp<=0){game.failed=true;$('startScreen').innerHTML='<div class="start-inner"><div class="start-kicker">SEÑAL PERDIDA</div><div class="start-logo">MISIÓN<br><span>COMPROMETIDA.</span></div><p>El agente ha sido detectado. Reagrupa y vuelve a intentarlo.</p><button class="primary-btn" id="againBtn">REINTENTAR <span>↻</span></button></div>';$('startScreen').classList.remove('hidden');$('againBtn').onclick=()=>freshGame(mapIndex);}}} }else if(g.state==='search'){g.look-=dt;if(g.look<=0){g.state='patrol';g.alerted=false;}}else{let pingTarget=null,best=Infinity;for(const n of game.noisePings){let d=Math.hypot(g.x-n.x,g.y-n.y);if(d<250&&d<best){best=d;pingTarget=n;}}for(const d of game.decoys){let distD=Math.hypot(g.x-d.x,g.y-d.y);if(distD<290&&distD<best){best=distD;pingTarget=d;}}if(pingTarget){g.state='investigate';g.angle=Math.atan2(pingTarget.y-g.y,pingTarget.x-g.x);moveToward(g,pingTarget.x,pingTarget.y,dt,g.speed*.8);if(best<18){g.state='search';g.look=2;}}else movePatrol(g,dt);}
    }
    if(game.alert>0&&!spotted)game.alert=Math.max(0,game.alert-dt*(game.alert>70?1.2:3));game.guards.forEach(g=>{if(g.state==='chase')spotted=true;});if(!spotted&&game.alert<8)game.guards.forEach(g=>{if(g.state==='search')g.state='patrol';});
    shotFx.forEach(s=>s.life-=dt);shotFx=shotFx.filter(s=>s.life>0);particles.forEach(a=>{a.life-=dt*1.2;a.x+=a.vx*dt;a.y+=a.vy*dt;});particles=particles.filter(a=>a.life>0);
    if(keys.KeyE&&game.cooldown<=0){interact();game.cooldown=.7;}if(keys.Space&&game.cooldown<=0){takedown();game.cooldown=.55;}if(keys.KeyQ&&game.cooldown<=0){useGadget();game.cooldown=.5;}updateHUD();
  }
}
function moveToward(g,x,y,dt,speed){const a=Math.atan2(y-g.y,x-g.x),nx=g.x+Math.cos(a)*speed*dt,ny=g.y+Math.sin(a)*speed*dt;if(!blocked(nx,g.y,g.r))g.x=nx;if(!blocked(g.x,ny,g.r))g.y=ny;}
function movePatrol(g,dt){if(!g.points.length)return;const target=g.points[g.index];const d=Math.hypot(target[0]-g.x,target[1]-g.y);if(d<7){g.index=(g.index+1)%g.points.length;g.look=.6;return;}g.angle=Math.atan2(target[1]-g.y,target[0]-g.x);moveToward(g,target[0],target[1],dt,g.speed);}
function updateHUD(){if(!game)return;const p=game.player;$('healthNum').textContent=Math.ceil(p.hp)+'%';$('healthBar').style.width=p.hp+'%';$('alertNum').textContent=Math.round(game.alert)+'%';$('alertBar').style.width=game.alert+'%';$('alertBar').style.background=game.alert>65?'var(--red)':game.alert>30?'var(--orange)':'var(--green)';$('score').textContent=String(game.score).padStart(5,'0');$('stealthBonus').textContent=`+ ${Math.max(0,Math.floor(400-game.alert*4))} SIGILO`;$('timeBonus').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;$('clock').textContent=$('timeBonus').textContent;$('enemyCount').textContent=`${game.guards.filter(g=>!g.civilian&&g.state!=='stun').length} HOSTILES`;
  const pill=document.querySelector('.status-pills .pill');let text='INVISIBLE',cls='';if(game.alert>65){text='COMPROMETIDO';cls='danger';}else if(game.alert>18){text='SOSPECHA';cls='alert';}else if(p.hidden)text='EN SOMBRAS';pill.className='pill '+cls; pill.innerHTML=`<i class="status-dot"></i><span id="statusText">${text}</span>`;$('alertBanner').classList.toggle('show',game.alert>35);$('coordinates').textContent=`GRID ${String(Math.floor(p.x/80)).padStart(2,'0')} / ${String(Math.floor(p.y/55)).padStart(2,'0')}`;}
function renderLoadout(){if(!game)return;$('weaponList').innerHTML=weapons.map((w,i)=>`<button class="weapon ${game.weapon===i?'active':''}" data-weapon="${i}"><span class="weapon-icon">${w.icon}</span><span><span class="weapon-name">${w.name}</span><small class="weapon-detail">${w.detail}</small></span><span class="ammo">${w.ammo}/${w.max}</span></button>`).join('');$('weaponList').querySelectorAll('[data-weapon]').forEach(b=>b.onclick=()=>{game.weapon=+b.dataset.weapon;renderLoadout();});$('gadgetList').innerHTML=gadgetDefs.map((g,i)=>`<button class="gadget ${selectedGadget===i?'selected':''}" data-gadget="${i}"><span class="g-icon">${g.icon}</span><b>${g.name}</b><small>×${game.gadgets[i]}</small></button>`).join('');$('gadgetList').querySelectorAll('[data-gadget]').forEach(b=>b.onclick=()=>{selectedGadget=+b.dataset.gadget;renderLoadout();});}

