+  window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='KeyE'&&game.cooldown<=0){interact();game.cooldown=.7;}if(e.code==='KeyQ'&&game.cooldown<=0){useGadget();game.cooldown=.5;}if(e.code==='Space'&&game.cooldown<=0){takedown();game.cooldown=.55;}if(e.code==='KeyF')whistle();if(e.code==='KeyR')reload();if(e.code==='Digit1'||e.code==='Digit2'||e.code==='Digit3'){game.weapon=Number(e.code.slice(-1))-1;renderLoadout();}if(e.code==='Escape'){keys={};}});
   window.addEventListener('keyup',e=>{keys[e.code]=false;});
   canvas.addEventListener('pointermove',e=>{setAim(e);});
   canvas.addEventListener('pointerdown',e=>{if(e.button===0){canvas.setPointerCapture?.(e.pointerId);setAim(e);pointer.down=true;fire();}});
